package br.com.coffeeflow.app;

import br.com.coffeeflow.config.Conexao;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.math.BigDecimal;
import java.sql.*;
import java.text.NumberFormat;
import java.time.LocalDate;
import java.util.*;

/** CoffeeFlow - Etapa 4: aplicação desktop integrada ao MySQL. */
public class Main {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            try { UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName()); } catch (Exception ignored) {}
            try (Connection ignored = Conexao.obterConexao()) {
                new CoffeeFlowWindow().setVisible(true);
            } catch (SQLException ex) {
                JOptionPane.showMessageDialog(null,
                    "Não foi possível conectar ao MySQL.\n\n" + ex.getMessage() +
                    "\n\nConfira se o MySQL está iniciado e execute database/CoffeeFlow.sql no Workbench.",
                    "Falha na conexão", JOptionPane.ERROR_MESSAGE);
            }
        });
    }
}

class CoffeeFlowWindow extends JFrame {
    private static final Color COFFEE = new Color(74,49,37), CREAM = new Color(248,245,239), ACCENT = new Color(191,126,75);
    private final CardLayout cards = new CardLayout();
    private final JPanel content = new JPanel(cards);
    private final Map<String, JTable> tables = new LinkedHashMap<>();
    private final Map<String, DefaultTableModel> models = new LinkedHashMap<>();
    private final Map<String, String> queries = new LinkedHashMap<>();
    private final JLabel breadcrumb = new JLabel("CoffeeFlow / Início");
    private String current = "Início";

    CoffeeFlowWindow() {
        super("CoffeeFlow | Gestão da cafeteria");
        setDefaultCloseOperation(EXIT_ON_CLOSE); setMinimumSize(new Dimension(1050,680)); setSize(1200,780); setLocationRelativeTo(null);
        queries.put("Produtos", "SELECT id_produto AS Código, nome AS Produto, preco_unitario AS `Preço (R$)` FROM produtos ORDER BY id_produto DESC");
        queries.put("Funcionários", "SELECT id_funcionario AS Código, nome AS Nome, cargo AS Cargo, nivel_acesso AS `Nível de acesso` FROM funcionarios ORDER BY id_funcionario DESC");
        queries.put("Insumos", "SELECT id_insumo AS Código, nome AS Insumo, quantidade_estoque AS `Quantidade em estoque` FROM insumos ORDER BY id_insumo DESC");
        queries.put("Receitas", "SELECT r.id_produto AS `Código produto`, p.nome AS Produto, r.id_insumo AS `Código insumo`, i.nome AS Insumo, r.quantidade_utilizada AS `Quantidade utilizada` FROM receita r JOIN produtos p ON p.id_produto=r.id_produto JOIN insumos i ON i.id_insumo=r.id_insumo ORDER BY p.nome,i.nome");
        queries.put("Pedidos", "SELECT p.id_pedido AS Pedido, DATE_FORMAT(p.data_pedido,'%d/%m/%Y %H:%i') AS Data, f.nome AS Funcionário, p.valor_total AS `Total (R$)` FROM pedidos p JOIN funcionarios f ON f.id_funcionario=p.id_funcionario ORDER BY p.id_pedido DESC");
        JPanel root = new JPanel(new BorderLayout()); root.setBackground(CREAM); root.add(sidebar(),BorderLayout.WEST);
        JPanel right = new JPanel(new BorderLayout()); right.setBackground(CREAM); right.add(topbar(),BorderLayout.NORTH);
        content.setBackground(CREAM); content.add(home(),"Início");
        for(String k:queries.keySet()) content.add(module(k),k);
        content.add(new JPanel(new BorderLayout()),"Relatórios"); right.add(content,BorderLayout.CENTER); root.add(right,BorderLayout.CENTER); setContentPane(root);
        refreshAll(); showPage("Início");
    }

    private JPanel sidebar(){
        JPanel p=new JPanel();p.setBackground(COFFEE);p.setPreferredSize(new Dimension(225,10));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.setBorder(new EmptyBorder(22,14,18,14));
        JLabel brand=new JLabel("☕ CoffeeFlow");brand.setForeground(Color.WHITE);brand.setFont(new Font("SansSerif",Font.BOLD,23));brand.setBorder(new EmptyBorder(5,10,28,0));p.add(brand);
        String[][] nav={{"Início","⌂"},{"Pedidos","▤"},{"Produtos","☕"},{"Insumos","◈"},{"Receitas","▧"},{"Funcionários","♙"},{"Relatórios","▥"}};
        for(String[] n:nav){JButton b=new JButton(n[1]+"   "+n[0]);b.setHorizontalAlignment(SwingConstants.LEFT);b.setForeground(new Color(246,239,229));b.setFont(new Font("SansSerif",Font.PLAIN,15));b.setFocusPainted(false);b.setBorder(new EmptyBorder(12,13,12,8));b.setContentAreaFilled(false);b.setMaximumSize(new Dimension(210,46));b.addActionListener(e->{if(n[0].equals("Relatórios"))refreshReports();showPage(n[0]);});p.add(b);p.add(Box.createVerticalStrut(3));}
        p.add(Box.createVerticalGlue());JLabel foot=new JLabel("  SISTEMA DE GESTÃO  ·  v2.0");foot.setForeground(new Color(208,190,170));foot.setFont(new Font("SansSerif",Font.PLAIN,10));p.add(foot);return p;
    }
    private JPanel topbar(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);p.setBorder(new EmptyBorder(18,30,10,30));breadcrumb.setFont(new Font("SansSerif",Font.PLAIN,14));p.add(breadcrumb,BorderLayout.WEST);JLabel user=new JLabel("●  Banco de dados conectado   ");user.setForeground(COFFEE);p.add(user,BorderLayout.EAST);return p;}
    private void showPage(String page){current=page;breadcrumb.setText("CoffeeFlow / "+page);cards.show(content,page);if(page.equals("Início"))refreshHome();if(queries.containsKey(page))refreshTable(page);}
    private JPanel pagePanel(){JPanel p=new JPanel(new BorderLayout());p.setBackground(CREAM);p.setBorder(new EmptyBorder(18,30,26,30));return p;}
    private JPanel heading(String h,String s){JPanel p=new JPanel();p.setOpaque(false);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel a=new JLabel(h);a.setFont(new Font("SansSerif",Font.BOLD,28));a.setForeground(COFFEE);JLabel b=new JLabel(s);b.setFont(new Font("SansSerif",Font.PLAIN,14));b.setForeground(new Color(120,111,101));p.add(a);p.add(Box.createVerticalStrut(5));p.add(b);return p;}
    private JPanel whiteCard(){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(232,225,215)),new EmptyBorder(18,18,18,18)));return p;}
    private JPanel stat(String label,String value,String note){JPanel p=whiteCard();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel a=new JLabel(label);a.setForeground(new Color(124,112,99));a.setFont(new Font("SansSerif",Font.BOLD,11));JLabel b=new JLabel(value);b.setForeground(COFFEE);b.setFont(new Font("SansSerif",Font.BOLD,24));JLabel c=new JLabel(note);c.setForeground(ACCENT);c.setFont(new Font("SansSerif",Font.PLAIN,12));p.add(a);p.add(Box.createVerticalStrut(13));p.add(b);p.add(Box.createVerticalStrut(5));p.add(c);return p;}
    private JPanel home(){JPanel p=pagePanel();p.setLayout(new BorderLayout(0,18));p.add(heading("Bom dia!","Acompanhe os dados reais da sua cafeteria."),BorderLayout.NORTH);JPanel body=new JPanel(new BorderLayout(0,20));body.setOpaque(false);JPanel stats=new JPanel(new GridLayout(1,4,14,0));stats.setOpaque(false);for(int i=0;i<4;i++)stats.add(stat("CARREGANDO","—","Aguardando MySQL"));body.add(stats,BorderLayout.NORTH);JPanel lower=new JPanel(new GridLayout(1,2,18,0));lower.setOpaque(false);JPanel recent=whiteCard();recent.setLayout(new BorderLayout());recent.add(new JLabel("Pedidos recentes"),BorderLayout.NORTH);recent.putClientProperty("recent",new JTextArea());recent.add((JTextArea)recent.getClientProperty("recent"),BorderLayout.CENTER);JPanel quick=whiteCard();quick.setLayout(new BoxLayout(quick,BoxLayout.Y_AXIS));JLabel q=new JLabel("Acesso rápido");q.setFont(new Font("SansSerif",Font.BOLD,17));quick.add(q);quick.add(Box.createVerticalStrut(18));String[][] acts={{"＋  Novo pedido","Pedidos"},{"☕  Cadastrar produto","Produtos"},{"◈  Atualizar estoque","Insumos"},{"▥  Ver relatórios","Relatórios"}};for(String[] a:acts){JButton b=button(a[0],false);b.setAlignmentX(LEFT_ALIGNMENT);b.setMaximumSize(new Dimension(400,43));b.addActionListener(e->{if(a[1].equals("Pedidos"))newOrder();else showPage(a[1]);});quick.add(b);quick.add(Box.createVerticalStrut(9));}lower.add(recent);lower.add(quick);body.add(lower,BorderLayout.CENTER);body.putClientProperty("stats",stats);body.putClientProperty("recent",recent);p.add(body,BorderLayout.CENTER);return p;}
    private JPanel module(String key){JPanel p=pagePanel();p.setLayout(new BorderLayout(0,16));p.add(heading(key,"Gerencie e consulte registros salvos no MySQL."),BorderLayout.NORTH);JPanel area=new JPanel(new BorderLayout(0,12));area.setOpaque(false);JPanel tools=new JPanel(new BorderLayout(8,0));tools.setOpaque(false);JTextField search=new JTextField();search.setPreferredSize(new Dimension(300,38));tools.add(search,BorderLayout.WEST);JPanel btns=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));btns.setOpaque(false);JButton refresh=button("Atualizar",false),edit=button("Editar",false),del=button("Excluir",false),add=button(key.equals("Pedidos")?"＋ Novo pedido":"＋ Adicionar",true);btns.add(refresh);btns.add(edit);btns.add(del);btns.add(add);tools.add(btns,BorderLayout.EAST);area.add(tools,BorderLayout.NORTH);DefaultTableModel model=new DefaultTableModel(){public boolean isCellEditable(int r,int c){return false;}};models.put(key,model);JTable table=new JTable(model);tables.put(key,table);table.setRowHeight(34);table.setFont(new Font("SansSerif",Font.PLAIN,13));table.getTableHeader().setFont(new Font("SansSerif",Font.BOLD,12));table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);area.add(new JScrollPane(table),BorderLayout.CENTER);p.add(area,BorderLayout.CENTER);search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){void f(){if(table.getRowSorter()==null)table.setAutoCreateRowSorter(true);((javax.swing.table.TableRowSorter<?>)table.getRowSorter()).setRowFilter(search.getText().isBlank()?null:RowFilter.regexFilter("(?i)"+java.util.regex.Pattern.quote(search.getText())));}public void insertUpdate(javax.swing.event.DocumentEvent e){f();}public void removeUpdate(javax.swing.event.DocumentEvent e){f();}public void changedUpdate(javax.swing.event.DocumentEvent e){f();}});refresh.addActionListener(e->refreshTable(key));edit.addActionListener(e->editRecord(key));add.addActionListener(e->{if(key.equals("Pedidos"))newOrder();else addRecord(key);});del.addActionListener(e->deleteRecord(key));return p;}
    private JButton button(String t,boolean primary){JButton b=new JButton(t);b.setFocusPainted(false);b.setFont(new Font("SansSerif",Font.BOLD,12));b.setBackground(primary?COFFEE:Color.WHITE);b.setForeground(primary?Color.WHITE:COFFEE);b.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(primary?COFFEE:new Color(220,211,199)),new EmptyBorder(9,13,9,13)));return b;}
    private void refreshAll(){for(String k:queries.keySet())refreshTable(k);refreshHome();refreshReports();}
    private void refreshTable(String key){DefaultTableModel m=models.get(key);if(m==null)return;try(Connection c=Conexao.obterConexao();Statement s=c.createStatement();ResultSet rs=s.executeQuery(queries.get(key))){m.setRowCount(0);m.setColumnCount(0);ResultSetMetaData md=rs.getMetaData();for(int i=1;i<=md.getColumnCount();i++)m.addColumn(md.getColumnLabel(i));while(rs.next()){Object[] row=new Object[md.getColumnCount()];for(int i=1;i<=row.length;i++)row[i-1]=rs.getObject(i);m.addRow(row);}}catch(SQLException ex){error("Não foi possível carregar "+key,ex);}}
    private void addRecord(String key){try(Connection c=Conexao.obterConexao()){
        switch(key){case "Produtos"->{String nome=ask("Nome do produto:");if(nome==null)return;BigDecimal preco=money("Preço unitário (ex.: 12,50):");if(preco==null)return;try(PreparedStatement p=c.prepareStatement("INSERT INTO produtos(nome,preco_unitario) VALUES(?,?)")){p.setString(1,nome);p.setBigDecimal(2,preco);p.executeUpdate();}}
        case "Funcionários"->{String nome=ask("Nome do funcionário:");if(nome==null)return;String cargo=ask("Cargo:");if(cargo==null)return;Integer nivel=integer("Nível de acesso (1 a 3):",1,3);if(nivel==null)return;try(PreparedStatement p=c.prepareStatement("INSERT INTO funcionarios(nome,cargo,nivel_acesso) VALUES(?,?,?)")){p.setString(1,nome);p.setString(2,cargo);p.setInt(3,nivel);p.executeUpdate();}}
        case "Insumos"->{String nome=ask("Nome do insumo:");if(nome==null)return;Integer qtd=integer("Quantidade inicial em estoque:",0,100000000);if(qtd==null)return;try(PreparedStatement p=c.prepareStatement("INSERT INTO insumos(nome,quantidade_estoque) VALUES(?,?)")){p.setString(1,nome);p.setInt(2,qtd);p.executeUpdate();}}
        case "Receitas"->{Integer prod=chooseId(c,"SELECT id_produto,nome FROM produtos ORDER BY nome","Selecione o produto:");if(prod==null)return;Integer ins=chooseId(c,"SELECT id_insumo,nome FROM insumos ORDER BY nome","Selecione o insumo:");if(ins==null)return;Integer qtd=integer("Quantidade utilizada:",1,1000000);if(qtd==null)return;try(PreparedStatement p=c.prepareStatement("INSERT INTO receita(id_produto,id_insumo,quantidade_utilizada) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantidade_utilizada=VALUES(quantidade_utilizada)")){p.setInt(1,prod);p.setInt(2,ins);p.setInt(3,qtd);p.executeUpdate();}}
        }refreshTable(key);message("Registro salvo no MySQL.");
    }catch(SQLException ex){error("Não foi possível salvar o registro",ex);}}
    private void editRecord(String key){JTable t=tables.get(key);int view=t.getSelectedRow();if(view<0){message("Selecione um registro para editar.");return;}int row=t.convertRowIndexToModel(view);try(Connection c=Conexao.obterConexao()){
        switch(key){case "Produtos"->{int id=((Number)models.get(key).getValueAt(row,0)).intValue();String nome=ask("Nome do produto:");if(nome==null)return;BigDecimal preco=money("Preço unitário:");if(preco==null)return;try(PreparedStatement p=c.prepareStatement("UPDATE produtos SET nome=?,preco_unitario=? WHERE id_produto=?")){p.setString(1,nome);p.setBigDecimal(2,preco);p.setInt(3,id);p.executeUpdate();}}
        case "Funcionários"->{int id=((Number)models.get(key).getValueAt(row,0)).intValue();String nome=ask("Nome:");if(nome==null)return;String cargo=ask("Cargo:");if(cargo==null)return;Integer nivel=integer("Nível de acesso (1 a 3):",1,3);if(nivel==null)return;try(PreparedStatement p=c.prepareStatement("UPDATE funcionarios SET nome=?,cargo=?,nivel_acesso=? WHERE id_funcionario=?")){p.setString(1,nome);p.setString(2,cargo);p.setInt(3,nivel);p.setInt(4,id);p.executeUpdate();}}
        case "Insumos"->{int id=((Number)models.get(key).getValueAt(row,0)).intValue();String nome=ask("Nome do insumo:");if(nome==null)return;Integer qtd=integer("Quantidade em estoque:",0,100000000);if(qtd==null)return;try(PreparedStatement p=c.prepareStatement("UPDATE insumos SET nome=?,quantidade_estoque=? WHERE id_insumo=?")){p.setString(1,nome);p.setInt(2,qtd);p.setInt(3,id);p.executeUpdate();}}
        case "Receitas"->{int prod=((Number)models.get(key).getValueAt(row,0)).intValue(),ins=((Number)models.get(key).getValueAt(row,2)).intValue();Integer qtd=integer("Nova quantidade utilizada:",1,1000000);if(qtd==null)return;try(PreparedStatement p=c.prepareStatement("UPDATE receita SET quantidade_utilizada=? WHERE id_produto=? AND id_insumo=?")){p.setInt(1,qtd);p.setInt(2,prod);p.setInt(3,ins);p.executeUpdate();}}
        case "Pedidos"->{message("Os pedidos registrados não podem ser editados nesta versão. Exclua e registre novamente se necessário.");return;}}
        refreshTable(key);message("Alterações atualizadas no MySQL.");
    }catch(SQLException ex){error("Não foi possível atualizar o registro",ex);}}
    private void deleteRecord(String key){JTable t=tables.get(key);int view=t.getSelectedRow();if(view<0){message("Selecione um registro para excluir.");return;}int row=t.convertRowIndexToModel(view);Object id=models.get(key).getValueAt(row,0);if(JOptionPane.showConfirmDialog(this,"Confirma a exclusão do registro "+id+"?","Confirmar",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;String sql=switch(key){case "Produtos"->"DELETE FROM produtos WHERE id_produto=?";case "Funcionários"->"DELETE FROM funcionarios WHERE id_funcionario=?";case "Insumos"->"DELETE FROM insumos WHERE id_insumo=?";case "Receitas"->"DELETE FROM receita WHERE id_produto=? AND id_insumo=?";case "Pedidos"->"DELETE FROM pedidos WHERE id_pedido=?";default->null;};if(sql==null)return;try(Connection c=Conexao.obterConexao()){if(key.equals("Pedidos")){c.setAutoCommit(false);try(PreparedStatement it=c.prepareStatement("DELETE FROM itens_pedidos WHERE id_pedido=?");PreparedStatement pd=c.prepareStatement("DELETE FROM pedidos WHERE id_pedido=?")){it.setObject(1,id);it.executeUpdate();pd.setObject(1,id);pd.executeUpdate();c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}else try(PreparedStatement p=c.prepareStatement(sql)){p.setObject(1,id);if(key.equals("Receitas"))p.setObject(2,models.get(key).getValueAt(row,2));p.executeUpdate();}refreshTable(key);message("Registro excluído do MySQL.");}catch(SQLException ex){error("Não foi possível excluir. Verifique se o registro está relacionado a outros dados.",ex);}}
    private void newOrder(){try(Connection c=Conexao.obterConexao()) {Integer funcionario=chooseId(c,"SELECT id_funcionario,nome FROM funcionarios ORDER BY nome","Selecione o funcionário:");if(funcionario==null)return;Integer produto=chooseId(c,"SELECT id_produto,CONCAT(nome,' — R$ ',FORMAT(preco_unitario,2,'pt_BR')) FROM produtos ORDER BY nome","Selecione o produto:");if(produto==null)return;Integer qtd=integer("Quantidade:",1,999);if(qtd==null)return; c.setAutoCommit(false);try{BigDecimal preco;try(PreparedStatement p=c.prepareStatement("SELECT preco_unitario FROM produtos WHERE id_produto=?")){p.setInt(1,produto);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Produto não encontrado.");preco=r.getBigDecimal(1);}}BigDecimal total=preco.multiply(BigDecimal.valueOf(qtd));int pedido;try(PreparedStatement p=c.prepareStatement("INSERT INTO pedidos(id_funcionario,valor_total) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,funcionario);p.setBigDecimal(2,total);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();pedido=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO itens_pedidos(id_pedido,id_produto,quantidade,subtotal) VALUES(?,?,?,?)")){p.setInt(1,pedido);p.setInt(2,produto);p.setInt(3,qtd);p.setBigDecimal(4,total);p.executeUpdate();}c.commit();message("Pedido #"+pedido+" salvo no banco. Total: "+brl(total));}catch(Exception ex){c.rollback();throw ex;}finally{c.setAutoCommit(true);}refreshTable("Pedidos");refreshHome();refreshReports();}catch(Exception ex){error("Não foi possível registrar o pedido",ex);}}
    private Integer chooseId(Connection c,String sql,String title)throws SQLException{java.util.List<String> labels=new ArrayList<>();java.util.List<Integer> ids=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){while(r.next()){ids.add(r.getInt(1));labels.add(r.getString(2));}}if(labels.isEmpty()){message("Cadastre os registros necessários antes.");return null;}Object selected=JOptionPane.showInputDialog(this,title,"CoffeeFlow",JOptionPane.QUESTION_MESSAGE,null,labels.toArray(),labels.get(0));return selected==null?null:ids.get(labels.indexOf(selected));}
    private String ask(String prompt){String s=JOptionPane.showInputDialog(this,prompt);return s==null||s.isBlank()?null:s.trim();}
    private Integer integer(String prompt,int min,int max){String s=ask(prompt);if(s==null)return null;try{int n=Integer.parseInt(s);if(n<min||n>max)throw new NumberFormatException();return n;}catch(NumberFormatException e){message("Informe um número válido entre "+min+" e "+max+".");return null;}}
    private BigDecimal money(String prompt){String s=ask(prompt);if(s==null)return null;try{BigDecimal n=new BigDecimal(s.replace(".","").replace(',','.'));if(n.signum()<=0)throw new NumberFormatException();return n;}catch(NumberFormatException e){message("Informe um preço válido maior que zero.");return null;}}
    private void refreshHome(){try(Connection c=Conexao.obterConexao()) {JPanel h=(JPanel)content.getComponent(0);JPanel body=(JPanel)((BorderLayout)h.getLayout()).getLayoutComponent(BorderLayout.CENTER);JPanel stats=(JPanel)body.getClientProperty("stats");String[][] v={{"VENDAS HOJE",scalar(c,"SELECT COALESCE(SUM(valor_total),0) FROM pedidos WHERE DATE(data_pedido)=CURDATE()"),"Faturamento registrado hoje"},{"PEDIDOS",scalar(c,"SELECT COUNT(*) FROM pedidos"),"Pedidos registrados"},{"PRODUTOS",scalar(c,"SELECT COUNT(*) FROM produtos"),"Produtos cadastrados"},{"ESTOQUE BAIXO",scalar(c,"SELECT COUNT(*) FROM insumos WHERE quantidade_estoque<=5"),"Insumos com até 5 unidades"}};stats.removeAll();for(String[] x:v)stats.add(stat(x[0],x[1],x[2]));JPanel recent=(JPanel)body.getClientProperty("recent");JTextArea ta=(JTextArea)recent.getClientProperty("recent");StringBuilder sb=new StringBuilder();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT p.id_pedido,DATE_FORMAT(p.data_pedido,'%H:%i'),f.nome,p.valor_total FROM pedidos p JOIN funcionarios f ON f.id_funcionario=p.id_funcionario ORDER BY p.id_pedido DESC LIMIT 6")){while(r.next())sb.append("#").append(r.getInt(1)).append("   ").append(r.getString(3)).append("   ").append(brl(r.getBigDecimal(4))).append("   ").append(r.getString(2)).append("\n\n");}ta.setText(sb.length()==0?"Nenhum pedido cadastrado.":sb.toString());h.revalidate();h.repaint();}catch(SQLException ex){error("Falha ao atualizar o painel",ex);}}
    private void refreshReports(){try(Connection c=Conexao.obterConexao()){BigDecimal faturamento=decimalScalar(c,"SELECT COALESCE(SUM(valor_total),0) FROM pedidos WHERE MONTH(data_pedido)=MONTH(CURRENT_DATE()) AND YEAR(data_pedido)=YEAR(CURRENT_DATE())");String pedidos=scalar(c,"SELECT COUNT(*) FROM pedidos WHERE MONTH(data_pedido)=MONTH(CURRENT_DATE()) AND YEAR(data_pedido)=YEAR(CURRENT_DATE())");String top=scalar(c,"SELECT COALESCE((SELECT p.nome FROM itens_pedidos i JOIN produtos p ON p.id_produto=i.id_produto GROUP BY p.id_produto,p.nome ORDER BY SUM(i.quantidade) DESC LIMIT 1),'—')");BigDecimal ticket=decimalScalar(c,"SELECT COALESCE(AVG(valor_total),0) FROM pedidos WHERE MONTH(data_pedido)=MONTH(CURRENT_DATE()) AND YEAR(data_pedido)=YEAR(CURRENT_DATE())");JPanel report=(JPanel)content.getComponent(content.getComponentCount()-1);report.removeAll();report.setLayout(new BorderLayout());report.add(heading("Relatórios","Indicadores calculados diretamente no MySQL."),BorderLayout.NORTH);JPanel b=new JPanel(new GridLayout(2,2,16,16));b.setOpaque(false);b.setBorder(new EmptyBorder(25,0,0,0));b.add(stat("FATURAMENTO DO MÊS",brl(faturamento),"Soma dos pedidos do mês"));b.add(stat("PEDIDOS NO MÊS",pedidos,"Pedidos registrados no mês"));b.add(stat("PRODUTO MAIS VENDIDO",top,"Com base nos itens dos pedidos"));b.add(stat("TICKET MÉDIO",brl(ticket),"Valor médio por pedido"));report.add(b,BorderLayout.CENTER);report.revalidate();report.repaint();}catch(SQLException ex){error("Falha ao calcular relatórios",ex);}}
    private BigDecimal decimalScalar(Connection c,String sql)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();BigDecimal v=r.getBigDecimal(1);return v==null?BigDecimal.ZERO:v;}}
    private String scalar(Connection c,String sql)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();Object v=r.getObject(1);return v instanceof BigDecimal?brl((BigDecimal)v):String.valueOf(v);}}
    private String brl(BigDecimal v){return NumberFormat.getCurrencyInstance(new Locale("pt","BR")).format(v==null?BigDecimal.ZERO:v);}
    private void message(String s){JOptionPane.showMessageDialog(this,s,"CoffeeFlow",JOptionPane.INFORMATION_MESSAGE);}
    private void error(String s,Exception ex){JOptionPane.showMessageDialog(this,s+":\n"+ex.getMessage(),"CoffeeFlow",JOptionPane.ERROR_MESSAGE);}
}
